import * as node_child_process from 'node:child_process';

/**
 * @param {string} nonce
 */
declare function detachedAdmissionMarker(nonce: string): string;
/**
 * @param {string} logFile
 * @param {number} [maxBytes]
 */
declare function readDetachedLogTail(logFile: string, maxBytes?: number): string;
/**
 * Wait until the engine child proves it persisted the run row. The child emits
 * the nonce from its RunStarted progress event, which is published only after
 * insertRun/activateRunForResume completes.
 *
 * The timeout bounds a child that died or wedged. A child that is still alive
 * at the deadline is given a grace window (`maxWaitMs`, default 4x the
 * timeout) because a loaded machine can spend the whole window on module
 * parse before the engine runs a line; `onSlowBoot` fires once when the grace
 * window begins.
 *
 * @param {{
 *   child: import("node:child_process").ChildProcess;
 *   logFile: string;
 *   nonce: string;
 *   timeoutMs?: number;
 *   maxWaitMs?: number;
 *   intervalMs?: number;
 *   onSlowBoot?: (info: { pid: number | undefined; elapsedMs: number; maxWaitMs: number }) => void;
 * }} options
 * @returns {Promise<
 *   { admitted: true; tail: string } |
 *   { admitted: false; reason: string; tail: string }
 * >}
 */
declare function waitForDetachedAdmission(options: {
    child: node_child_process.ChildProcess;
    logFile: string;
    nonce: string;
    timeoutMs?: number;
    maxWaitMs?: number;
    intervalMs?: number;
    onSlowBoot?: (info: {
        pid: number | undefined;
        elapsedMs: number;
        maxWaitMs: number;
    }) => void;
}): Promise<{
    admitted: true;
    tail: string;
} | {
    admitted: false;
    reason: string;
    tail: string;
}>;
/**
 * @param {import("node:child_process").ChildProcess} child
 */
declare function terminateUnadmittedChild(child: node_child_process.ChildProcess): void;
declare const DETACHED_ADMISSION_NONCE_ENV: "SMITHERS_DETACHED_ADMISSION_NONCE";
declare const DETACHED_ADMISSION_TIMEOUT_ENV: "SMITHERS_DETACHED_ADMISSION_TIMEOUT_MS";
declare const DETACHED_ADMISSION_TIMEOUT_MS: number;

export { DETACHED_ADMISSION_NONCE_ENV, DETACHED_ADMISSION_TIMEOUT_ENV, DETACHED_ADMISSION_TIMEOUT_MS, detachedAdmissionMarker, readDetachedLogTail, terminateUnadmittedChild, waitForDetachedAdmission };
